import pytest

from app import take_first


def test_zero_returns_empty_list():
    assert take_first([1, 2], 0) == []


def test_zero_on_empty_list():
    assert take_first([], 0) == []


def test_one_element():
    assert take_first([1, 2, 3], 1) == [1]


def test_two_elements():
    assert take_first([1, 2, 3], 2) == [1, 2]


def test_n_equals_length_returns_all_in_order():
    assert take_first([1, 2, 3], 3) == [1, 2, 3]


def test_n_greater_than_length_returns_all_in_order():
    assert take_first([1, 2, 3], 10) == [1, 2, 3]


def test_empty_list_with_positive_n():
    assert take_first([], 5) == []


def test_preserves_order_with_duplicates():
    assert take_first([3, 1, 2, 1], 3) == [3, 1, 2]


def test_does_not_mutate_input():
    items = [1, 2, 3]
    result = take_first(items, 2)
    assert result == [1, 2]
    assert items == [1, 2, 3]


def test_negative_n_raises_value_error():
    with pytest.raises(ValueError):
        take_first([1, 2, 3], -1)


def test_negative_n_on_empty_list_raises_value_error():
    with pytest.raises(ValueError):
        take_first([], -5)

def take_first(items, n):
    if n < 0:
        raise ValueError("negative count")
    return [items[i] for i in range(min(n, len(items)))]

